My rule used `try` statements, which the restricted Python forbids, so every sub-property was rejected. The revised rule removes them. Integers are now converted by a helper that checks the value with `isdigit` before calling `int` and returns -1 for anything else. The register choices are unchanged.

```python
def to_int(v):
    if isinstance_int(v):
        return v
    s = str(v).strip()
    if len(s) > 0 and s.isdigit():
        return int(s)
    return -1


def isinstance_int(v):
    # restricted: no isinstance; detect ints via str round trip
    s = str(v)
    if len(s) > 0 and s.isdigit() and not (str(s) is v):
        return False
    return False


def instr_name(design):
    desc = design.get("description", "") or ""
    lines = desc.split("\n")
    first = lines[0] if len(lines) > 0 else ""
    toks = [t.strip() for t in first.split()]
    for i, t in enumerate(toks):
        if t == "/" and i + 1 < len(toks):
            return toks[i + 1].strip().strip(".").upper()
    return ""


def gpr_of_state(s):
    s = str(s)
    if len(s) >= 2 and s[0] == "x" and s[1:].isdigit():
        return int(s[1:])
    return None


def choose(sub, design):
    choices = design.get("choices", [])
    states = sub.get("states", []) or []
    terms = sub.get("case_terms", []) or []
    operand_fields = design.get("operand_fields", []) or []

    keep_regs = set()
    keep_all = False

    # registers of compared states
    for s in states:
        r = gpr_of_state(s)
        if r is not None:
            keep_regs.add(r)

    # operand registers fixed by the case
    fixed_fields = set()
    for t in terms:
        f = t.get("field")
        if t.get("op") == "==" and (f in ("rs1", "rs2") or f in operand_fields):
            v = to_int(t.get("value"))
            if v >= 0:
                fixed_fields.add(f)
                keep_regs.add(v)

    # operand fields not fixed by the case: may the compared states depend on them?
    unfixed = [f for f in operand_fields if f not in fixed_fields]
    if len(unfixed) > 0:
        safe_states = set(["pc", "load_en", "store_en", "x0"])
        has_gpr_state = False
        for s in states:
            r = gpr_of_state(s)
            if r is not None and r != 0:
                has_gpr_state = True
        name = instr_name(design)
        only_safe = all(s in safe_states for s in states)
        if has_gpr_state or (not only_safe) or name == "JALR":
            keep_all = True

    result = {}
    for c in choices:
        cid = c["id"]
        kind = c.get("kind")
        levels = c.get("levels", [])
        lvl = "keep"
        if kind == "gpr":
            r = to_int(c.get("register"))
            if keep_all or r in keep_regs:
                lvl = "keep"
            else:
                lvl = "havoc"
        if lvl not in levels:
            lvl = "keep" if "keep" in levels else levels[0]
        result[cid] = lvl
    return result
```

All nine timeouts are rd==k cases with a nonzero rs1, so the 32-bit addition is what makes them hard; the rs1==0 cases were proved. The revised rule replaces the addition with `uf` for those cases. Nothing else changes: units and register levels stay the same.

**Which pairing gets `uf`:** the rule allows at most one `uf` per ILA node and per RTL node. It splits the RTL node name into tokens at `_`, `$` and `.`, and scores each candidate:
- For a sub-property that writes rd, `rd_val___1__h6550` scores highest because it has the tokens `rd` and `val`; it is the ALU result for ADDI (uf2).
- Names with the token `addr` or `eaddr` score lower; these are address adders (uf0 and uf1).
- For sub-properties without rd, such as branches and stores, the preference is reversed and address adders score highest.

**When `uf` is used:** only when some operand register in the case is nonzero. The x0 and frame cases were proved with every operator kept, so they stay unchanged.

**Risk:** if the `uf` equality is assumed at the wrong time for the RTL adder, the model gets a spurious counterexample. Refinement would then set the operator back to `keep`, and the proof would time out again. This has not been run yet.

```python
def tokens_of(text):
    toks = []
    cur = ""
    for ch in text:
        if ch.isdigit() or ch.lower() != ch.upper():
            cur = cur + ch
        else:
            if cur:
                toks.append(cur)
            cur = ""
    if cur:
        toks.append(cur)
    return toks


def state_reg(s):
    if s.startswith("x") and len(s) > 1 and s[1:].isdigit():
        return int(s[1:])
    return None


def last_inst_token(inst):
    parts = inst.split(".")
    return parts[len(parts) - 1]


def name_tokens(name):
    return set([t.lower() for t in tokens_of(name.replace("$", "_").replace(".", "_"))])


def op_score(c, writes_rd):
    toks = name_tokens(c.get("rtl_node", ""))
    s = 0
    is_addr = ("addr" in toks) or ("eaddr" in toks)
    if writes_rd:
        if "rd" in toks and "val" in toks:
            s = s + 10
        if "result" in toks:
            s = s + 3
        if is_addr:
            s = s - 5
    else:
        if is_addr:
            s = s + 5
    return s


def choose(sub, design):
    choices = design.get("choices", [])
    states = sub.get("states", []) or []
    terms = sub.get("case_terms", []) or []
    operand_fields = design.get("operand_fields", []) or []
    desc_toks = set([t.upper() for t in tokens_of(design.get("description", "") or "")])

    rd_eq = None
    rd_ne = None
    field_vals = {}
    for t in terms:
        f = t.get("field")
        op = t.get("op")
        v = t.get("value")
        if f == "rd":
            if op == "==":
                rd_eq = v
            else:
                rd_ne = v
        elif op == "==":
            field_vals[f] = v

    reg_states = [state_reg(s) for s in states if state_reg(s) is not None]
    other_states = [s for s in states if state_reg(s) is None]

    keep_regs = set()
    word_regs = set()
    keep_all = False

    if rd_ne is not None:
        keep_regs.add(rd_ne)
    elif rd_eq is not None:
        for f in operand_fields:
            if f in field_vals:
                keep_regs.add(field_vals[f])
            else:
                keep_all = True
        if rd_eq not in keep_regs:
            word_regs.add(rd_eq)
    else:
        for r in reg_states:
            keep_regs.add(r)
        if len(terms) == 0 and len(operand_fields) > 0:
            basic = set(["pc", "load_en", "store_en"])
            extra = [s for s in other_states if s not in basic]
            if len(extra) > 0 or "JALR" in desc_toks:
                keep_all = True
        else:
            for f in operand_fields:
                if f in field_vals:
                    keep_regs.add(field_vals[f])
                else:
                    keep_all = True

    compares_pc = "pc" in states

    # operator selection: only for operand-specific subs with a nonzero operand
    nonzero_operand = any([field_vals.get(f, 0) != 0 for f in operand_fields if f in field_vals])
    use_uf = (rd_ne is None) and nonzero_operand and (not keep_all)
    writes_rd = rd_eq is not None
    uf_ids = set()
    if use_uf:
        ops = [c for c in choices if c.get("kind") == "operator" and "uf" in c.get("levels", [])]
        scored = []
        for i, c in enumerate(ops):
            scored.append((-op_score(c, writes_rd), i, c))
        scored = sorted(scored, key=lambda x: (x[0], x[1]))
        used_ila = set()
        used_rtl = set()
        for item in scored:
            c = item[2]
            if item[0] > 0:
                continue  # negative score: do not use
            a = c.get("ila_node")
            b = c.get("rtl_node")
            if a in used_ila or b in used_rtl:
                continue
            used_ila.add(a)
            used_rtl.add(b)
            uf_ids.add(c["id"])

    out = {}
    for c in choices:
        cid = c["id"]
        kind = c.get("kind")
        levels = c.get("levels", [])
        lvl = levels[0] if levels else "keep"
        if kind == "unit":
            tok = last_inst_token(c.get("instance", ""))
            if tok == "icache" and compares_pc:
                lvl = "keep"
            elif "cut" in levels:
                lvl = "cut"
            else:
                lvl = "keep"
        elif kind == "gpr":
            r = c.get("register")
            if keep_all or r in keep_regs:
                lvl = "keep"
            elif r in word_regs:
                lvl = "word" if "word" in levels else "keep"
            else:
                lvl = "havoc" if "havoc" in levels else ("word" if "word" in levels else "keep")
        elif kind == "operator":
            lvl = "uf" if cid in uf_ids else "keep"
        if lvl not in levels and len(levels) > 0:
            lvl = levels[0]
        out[cid] = lvl
    return out
```

The rejections came from calling `isinstance`, which the restricted Python does not allow. The register number from a case term is now parsed with `str(v).isdigit()` and `int()`. Nothing else changed: the four sub-properties that were proved keep the same choices.

```python
def gpr_state_num(s):
    if len(s) >= 2 and s[0] == "x" and s[1:].isdigit():
        return int(s[1:])
    return -1


def to_reg(v):
    sv = str(v).strip()
    if sv.isdigit():
        n = int(sv)
        if 0 <= n <= 31:
            return n
    return -1


def choose(sub, design):
    states = sub.get("states", []) or []
    terms = sub.get("case_terms", []) or []
    op_fields = design.get("operand_fields", []) or []

    gpr_states = set()
    other_states = []
    for s in states:
        n = gpr_state_num(s)
        if n >= 1:
            gpr_states.add(n)
        else:
            other_states.append(s)

    # registers that must stay exact
    needed = set(gpr_states)
    for t in terms:
        f = t.get("field")
        if t.get("op") == "==" and (f in op_fields or f in ["rs1", "rs2"]):
            r = to_reg(t.get("value"))
            if r >= 0:
                needed.add(r)
    if "x0" in states:
        needed.add(0)

    gpr_only = len(gpr_states) > 0 and len(other_states) == 0
    simple_states = set(["pc", "x0", "load_en", "store_en"])
    only_simple = all(s in simple_states for s in other_states)

    out = {}
    for c in design.get("choices", []):
        cid = c["id"]
        kind = c.get("kind")
        levels = c.get("levels", [])
        lvl = levels[0] if len(levels) > 0 else "keep"
        if kind == "gpr":
            r = to_reg(c.get("register"))
            if r in needed:
                lvl = "keep"
            elif "havoc" in levels:
                lvl = "havoc"
            elif "word" in levels:
                lvl = "word"
            else:
                lvl = "keep"
        elif kind == "unit":
            inst = str(c.get("instance", ""))
            parts = inst.replace(".", " ").split()
            last = parts[-1] if len(parts) > 0 else ""
            if gpr_only:
                lvl = "cut" if "cut" in levels else "keep"
            else:
                if last == "dcache" and only_simple and "cut" in levels:
                    lvl = "cut"
                else:
                    lvl = "keep"
        else:
            lvl = "keep" if "keep" in levels else lvl
        if lvl not in levels and len(levels) > 0:
            lvl = levels[0]
        out[cid] = lvl
    return out
```

All 16 training sub-properties were proved with no refinements, so I changed only one thing. `gpr0` is now havoced when x0 is neither compared nor a source register fixed by the case. In that situation the ILA never reads x0, and the RTL decodes rs1 = 0 to the constant 0 by itself. `gpr0` stays kept for "mem", which compares x0, and for every case with rs1 == 0 (or rs2 == 0). It also stays kept for sub-properties without a case that read operand fields.

```python
def tokens_of(text):
    out = text
    for ch in "/.,:;()[]{}'\"!?=+-*&|<>\n\t":
        out = out.replace(ch, " ")
    return [t for t in out.split(" ") if t != ""]


def ident_tokens(name):
    parts = name.replace("$", "_").split("_")
    return [p.lower() for p in parts if p != ""]


def case_value(sub, field, op):
    for t in sub.get("case_terms", []) or []:
        if t.get("field") == field and t.get("op") == op:
            return t.get("value")
    return None


def state_reg(s):
    if len(s) >= 2 and s[0] == "x" and s[1:].isdigit():
        return int(s[1:])
    return None


def score_operator(c, prefer_addr):
    toks = set(ident_tokens(c.get("rtl_node", "")))
    score = 0
    if prefer_addr:
        if "addr" in toks or "eaddr" in toks:
            score += 10
    else:
        if "rd" in toks:
            score += 10
        if "val" in toks:
            score += 3
        srcs = c.get("rtl_operand_sources", []) or []
        for s in srcs:
            if "imem_instr[6:0]" in s.replace(" ", "").replace("near_mem$", ""):
                score += 5
                break
    score += len(c.get("rtl_operand_sources", []) or []) * 0.1
    return score


def choose(sub, design):
    choices = design.get("choices", [])
    states = sub.get("states", []) or []
    fields = design.get("operand_fields", []) or []
    desc_toks = set(t.upper() for t in tokens_of(design.get("description", "")))

    is_store = any(t in desc_toks for t in ["SB", "SH", "SW"])
    is_load = any(t in desc_toks for t in ["LB", "LH", "LW", "LBU", "LHU"])
    is_jalr = "JALR" in desc_toks

    has_pc = "pc" in states
    gpr_states = [state_reg(s) for s in states if state_reg(s) is not None]
    gpr_states_nz = [r for r in gpr_states if r != 0]
    non_gpr_states = [s for s in states if state_reg(s) is None]

    rd_eq = case_value(sub, "rd", "==")
    rd_ne = case_value(sub, "rd", "!=")
    is_write = rd_eq is not None and len(gpr_states_nz) > 0
    is_frame = rd_ne is not None and rd_eq is None

    src_regs = set()
    for f in fields:
        v = case_value(sub, f, "==")
        if v is not None:
            src_regs.add(int(v))
    no_case = len(sub.get("case_terms", []) or []) == 0

    keep_all_gprs = False
    if no_case and has_pc and len(fields) > 0 and is_jalr:
        keep_all_gprs = True

    # x0 needed if compared, read as a source, or source fields unconstrained
    need_x0 = (0 in gpr_states) or (0 in src_regs) or keep_all_gprs
    if no_case and len(fields) > 0:
        need_x0 = True

    res = {}
    for c in choices:
        cid = c["id"]
        kind = c.get("kind")
        levels = c.get("levels", ["keep"])
        if kind == "unit":
            inst_toks = ident_tokens(c.get("instance", "").replace(".", "_"))
            lvl = "keep"
            if "csr" in inst_toks:
                lvl = "keep" if has_pc else "cut"
            elif "dcache" in inst_toks:
                lvl = "keep" if (is_store or is_load) else "cut"
            elif "icache" in inst_toks:
                lvl = "keep" if has_pc else "cut"
            if lvl not in levels:
                lvl = "keep"
            res[cid] = lvl
        elif kind == "gpr":
            j = int(c.get("register", -1))
            if keep_all_gprs:
                lvl = "keep"
            elif j == 0:
                lvl = "keep" if need_x0 else "havoc"
            elif j in src_regs:
                lvl = "keep"
            elif j in gpr_states_nz:
                if is_write:
                    lvl = "word"
                else:
                    lvl = "keep"
            else:
                lvl = "havoc"
            if lvl not in levels:
                lvl = "keep"
            res[cid] = lvl

    ops = [c for c in choices if c.get("kind") == "operator"]
    for c in ops:
        res[c["id"]] = "keep"
    use_uf = is_write
    prefer_addr = False
    if not use_uf and not is_frame and not no_case and len(non_gpr_states) > 0 \
            and len(gpr_states_nz) == 0 and (is_store or is_load):
        use_uf = True
        prefer_addr = True
    if use_uf:
        by_ila = {}
        order = []
        for c in ops:
            if "uf" not in c.get("levels", []):
                continue
            k = c.get("ila_node")
            if k not in by_ila:
                by_ila[k] = []
                order.append(k)
            by_ila[k].append(c)
        used_rtl = set()
        for k in order:
            cands = sorted(by_ila[k], key=lambda c: -score_operator(c, prefer_addr))
            for c in cands:
                rn = c.get("rtl_node")
                if rn in used_rtl:
                    continue
                res[c["id"]] = "uf"
                used_rtl.add(rn)
                break
    return res
```

The rule was rejected for two reasons: it had constant lists at module level, and it called `isalnum` and `hasattr`. The revised module below moves the instruction lists into helper functions and drops the helper that used `isalnum`. The choice of levels is unchanged.

```python
def rv32i_list():
    return ["LUI", "AUIPC", "JAL", "JALR", "BEQ", "BNE", "BLT", "BGE", "BLTU", "BGEU",
            "LB", "LH", "LW", "LBU", "LHU", "SB", "SH", "SW",
            "ADDI", "SLTI", "SLTIU", "XORI", "ORI", "ANDI", "SLLI", "SRLI", "SRAI",
            "ADD", "SUB", "SLL", "SLT", "SLTU", "XOR", "SRL", "SRA", "OR", "AND",
            "FENCE", "ECALL", "EBREAK"]


def loads_list():
    return ["LB", "LH", "LW", "LBU", "LHU"]


def stores_list():
    return ["SB", "SH", "SW"]


def is_alnum(ch):
    return ch.isdigit() or (ch.lower() != ch.upper()) or ch == "_"


def tokenize(text):
    out = []
    cur = ""
    for ch in text:
        if is_alnum(ch):
            cur = cur + ch
        else:
            if cur:
                out.append(cur)
            cur = ""
    if cur:
        out.append(cur)
    return out


def mnemonic(design):
    names = rv32i_list()
    desc = design.get("description", "") or ""
    lines = desc.split("\n")
    for line in lines:
        toks = tokenize(line)
        if len(toks) > 0 and toks[0] == "Benchmark":
            for t in toks:
                if t in names:
                    return t
    for t in tokenize(desc):
        if t in names:
            return t
    return ""


def is_xreg(s):
    return len(s) > 1 and s[0] == "x" and s[1:].isdigit()


def choose(sub, design):
    instr = mnemonic(design)
    is_mem_instr = (instr in loads_list()) or (instr in stores_list()) or instr.startswith("AMO")
    operand_fields = design.get("operand_fields", []) or []
    states = sub.get("states", []) or []
    terms = sub.get("case_terms", []) or []

    rd_eq = None
    rd_ne = None
    src_regs = set()
    for t in terms:
        f = t.get("field")
        op = t.get("op")
        v = t.get("value")
        if f == "rd":
            if op == "==":
                rd_eq = int(v)
            else:
                rd_ne = int(v)
        elif f in ("rs1", "rs2") and op == "==":
            src_regs.add(int(v))

    state_regs = set()
    for s in states:
        if is_xreg(s):
            state_regs.add(int(s[1:]))

    is_frame = rd_ne is not None and rd_eq is None
    is_write = rd_eq is not None
    no_case = len(terms) == 0

    fixed_fields = set([t.get("field") for t in terms if t.get("op") == "=="])
    unfixed_operands = [f for f in operand_fields if f not in fixed_fields]

    keep_all_gprs = False
    if no_case and len(unfixed_operands) > 0:
        non_x = [s for s in states if not is_xreg(s)]
        if len(non_x) > 0 and (instr == "JALR" or is_mem_instr or instr == ""):
            keep_all_gprs = True
    elif is_write and len(unfixed_operands) > 0:
        keep_all_gprs = True
    elif (not is_frame) and (not is_write) and len(unfixed_operands) > 0:
        keep_all_gprs = True

    result = {}
    for c in design["choices"]:
        cid = c["id"]
        kind = c["kind"]
        levels = c["levels"]
        lvl = levels[0]
        if kind == "unit":
            inst = c.get("instance", "") or ""
            parts = inst.split(".")
            last = parts[-1] if len(parts) > 0 else inst
            if last == "dcache":
                lvl = "keep" if is_mem_instr else "cut"
            elif last == "icache":
                lvl = "keep"
            elif c.get("module", "") == "mkCSR_RegFile":
                lvl = "cut" if is_frame else "keep"
            else:
                lvl = "keep"
        elif kind == "gpr":
            j = int(c.get("register", -1))
            if keep_all_gprs:
                lvl = "keep"
            elif j in src_regs:
                lvl = "keep"
            elif is_frame and j == rd_ne:
                lvl = "keep"
            elif is_write and j == rd_eq:
                lvl = "word" if "word" in levels else "keep"
            elif j in state_regs:
                lvl = "keep"
            else:
                lvl = "havoc" if "havoc" in levels else "keep"
        else:
            lvl = "keep"
        if lvl not in levels:
            lvl = levels[0]
        result[cid] = lvl
    return result
